# Writes the expressions of a model generated by PySD's Julia builder with
# only the parentheses they need:
#
#   julia tidy.jl model.jl [more.jl ...]
#
# Each statement on one line is printed again by Julia's own printer, which
# writes only the parentheses the expression needs: the expression is the same
# (((a * b) * c) becomes a * b * c, pysd_ifelse((t < 2015.0), ...) becomes
# pysd_ifelse(t < 2015.0, ...)).  Comments, and lines that are not a whole
# statement, are kept as they are.  No packages are needed.

# a statement as code: an assignment or a call
function _statement(code::AbstractString)
    ex = try
        Meta.parse(code; raise = true)
    catch
        return nothing
    end
    (ex isa Expr && ex.head in (:(=), :(.=), :call)) || return nothing
    return ex
end

# (a + b) + c as a + b + c (and the same for *): Julia defines
# +(a, b, c) as (a + b) + c, so the result is the same
_flatten(x) = x
function _flatten(ex::Expr)
    args = map(_flatten, ex.args)
    if ex.head === :call && args[1] in (:+, :*) && length(args) >= 3
        first = args[2]
        if first isa Expr && first.head === :call && first.args[1] === args[1] &&
           length(first.args) >= 3
            return Expr(:call, args[1], first.args[2:end]..., args[3:end]...)
        end
    end
    return Expr(ex.head, args...)
end

# the statement printed again, or nothing (anonymous functions, macros,
# interpolation and blocks are printed in other ways: kept as they are)
function _reprint(code::AbstractString)
    occursin(r"->|@|\$|\bdo\b|\bbegin\b|\bfunction\b|\bend\b", code) && return nothing
    ex = _statement(code)
    ex === nothing && return nothing
    text = string(_flatten(ex))
    occursin('\n', text) && return nothing
    # the printed statement must read back as the same expression
    Meta.parse(text) == _flatten(ex) || return nothing
    return text
end

# where a trailing comment starts, outside strings
function _comment_start(line::AbstractString)
    in_string = false
    prev = ' '
    for (i, c) in pairs(line)
        if c == '"' && prev != '\\'
            in_string = !in_string
        elseif c == '#' && !in_string
            return i
        end
        prev = c
    end
    return nothing
end

function tidy(path::AbstractString)
    out = String[]
    for line in readlines(path)
        stripped = lstrip(line)
        if isempty(stripped) || startswith(stripped, '#')
            push!(out, line)
            continue
        end
        indent = line[1:(length(line) - length(stripped))]
        c = _comment_start(stripped)
        code, comment = c === nothing ? (String(stripped), "") :
                        (String(rstrip(stripped[1:prevind(stripped, c)])),
                         "  " * stripped[c:end])
        text = _reprint(code)
        push!(out, text === nothing ? line : indent * text * comment)
    end
    write(path, join(out, '\n') * '\n')
    return path
end

foreach(tidy, ARGS)
